import json,hashlib
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
out=Path(__file__).parent;root=out.parent;manifest=json.loads((root/'evidence/version.json').read_text());original=root.parent/'core-journey-lowfi';om=(original/'evidence/version.json').read_bytes();checks=[]
def fingerprint():return {f:hashlib.sha256((root/f).read_bytes()).hexdigest()==h for f,h in manifest['sha256'].items()}
def original_ok():
 m=json.loads((original/'evidence/version.json').read_text());return {'manifestUnchanged':(original/'evidence/version.json').read_bytes()==om,'files':len(m['sha256']),'mismatches':[f for f,h in m['sha256'].items() if hashlib.sha256((original/f).read_bytes()).hexdigest()!=h]}
def note(n,d):checks.append({'check':n,'observed':d});(out/'studio-independent-checks.json').write_text(json.dumps(checks,indent=2,ensure_ascii=False),encoding='utf-8');print(n,str(d)[:300],flush=True)
def shot(page,n):page.screenshot(path=str(out/(n+'.png')))
def st(page):return page.evaluate('JSON.parse(localStorage.getItem("dubbed-studio-lowfi-v1"))')
def opt(page,id,v=True):
 page.locator('.lab summary').click()
 if id=='#locale':page.locator(id).select_option(v)
 else:page.locator(id).set_checked(v)
 page.locator('.lab summary').click()
def dots(page,n):
 d=page.locator('#dots span').evaluate_all('(es)=>es.map(e=>({current:e.getAttribute("aria-current"),role:e.getAttribute("role"),tabindex:e.getAttribute("tabindex")}))');assert len(d)==3 and [x['current'] for x in d].count('true')==1 and d[n-1]['current']=='true';assert page.locator('#dots button,#dots a').count()==0;return d

